//! Synthetic images only: generated bytes laid out as XDVDFS.
use super::xdvdfs::{Error, Image, SECTOR};
use super::*;
use std::io::Cursor;

enum Node {
    File(&'static str, Vec<u8>),
    Dir(&'static str, Vec<Node>),
}

/// Builds an image with the game partition at `partition`. Each directory
/// is a right-leaning chain of entries.
fn image(partition: u64, root: Vec<Node>) -> Vec<u8> {
    let mut sectors: Vec<Vec<u8>> = Vec::new();
    let (sector, size) = place(&mut sectors, &root, 34);
    let mut out = vec![0u8; (partition + 34 * SECTOR) as usize];
    let at = (partition + 32 * SECTOR) as usize;
    out[at..at + 20].copy_from_slice(b"MICROSOFT*XBOX*MEDIA");
    out[at + 20..at + 24].copy_from_slice(&sector.to_le_bytes());
    out[at + 24..at + 28].copy_from_slice(&size.to_le_bytes());
    for s in sectors {
        out.extend_from_slice(&s);
    }
    out
}

/// Writes `nodes` as a directory starting at sector `next + used`.
fn place(sectors: &mut Vec<Vec<u8>>, nodes: &[Node], first: u32) -> (u32, u32) {
    let dir_sector = first + sectors.len() as u32;
    sectors.push(Vec::new());
    let slot = sectors.len() - 1;
    let mut placed = Vec::new();
    for node in nodes {
        match node {
            Node::File(name, bytes) => {
                let s = first + sectors.len() as u32;
                let mut padded = bytes.clone();
                padded.resize(
                    bytes.len().div_ceil(SECTOR as usize).max(1) * SECTOR as usize,
                    0,
                );
                sectors.push(padded);
                placed.push((*name, s, bytes.len() as u32, 0u8));
            }
            Node::Dir(name, children) => {
                let (s, size) = place(sectors, children, first);
                placed.push((*name, s, size, 0x10));
            }
        }
    }
    let mut dir = Vec::new();
    for (i, (name, s, size, attr)) in placed.iter().enumerate() {
        let len = (14 + name.len()).div_ceil(4) * 4;
        let right = if i + 1 < placed.len() {
            ((dir.len() + len) / 4) as u16
        } else {
            0
        };
        dir.extend_from_slice(&0u16.to_le_bytes());
        dir.extend_from_slice(&right.to_le_bytes());
        dir.extend_from_slice(&s.to_le_bytes());
        dir.extend_from_slice(&size.to_le_bytes());
        dir.push(*attr);
        dir.push(name.len() as u8);
        dir.extend_from_slice(name.as_bytes());
        dir.resize(dir.len().div_ceil(4) * 4, 0);
    }
    let size = dir.len() as u32;
    dir.resize(SECTOR as usize, 0xFF);
    sectors[slot] = dir;
    (dir_sector, size)
}

fn skate_layout(xex: &[u8]) -> Vec<Node> {
    vec![
        Node::File("default.xex", xex.to_vec()),
        Node::Dir(
            "data",
            vec![
                Node::Dir(
                    "big",
                    vec![
                        Node::File("miscload.big", vec![1]),
                        Node::File("miscboot.big", vec![2]),
                        Node::File("db.big", vec![3]),
                    ],
                ),
                Node::Dir(
                    "content",
                    vec![Node::File("CreateACharacter.big", b"synthetic".to_vec())],
                ),
            ],
        ),
    ]
}

#[test]
fn finds_and_reads_files_case_insensitively() {
    for partition in [0, 0x0208_0000] {
        let bytes = image(partition, skate_layout(b"XEX2synthetic"));
        let mut img = Image::open(Cursor::new(bytes)).unwrap();
        let entry = img
            .find("DATA/content/createacharacter.big")
            .unwrap()
            .unwrap();
        assert!(!entry.directory);
        assert_eq!(img.read(&entry, 0, 9).unwrap(), b"synthetic");
        assert!(img.find("data/big/missing.big").unwrap().is_none());
        assert!(img.find("default.xex/inner").unwrap().is_none());
        check_image(&mut img).unwrap();
    }
}

#[test]
fn rejects_non_xbox_images_and_missing_files() {
    assert!(matches!(
        Image::open(Cursor::new(vec![0u8; 0x20000])),
        Err(Error::NotXdvdfs)
    ));
    let mut layout = skate_layout(b"XEX2");
    layout.truncate(1);
    let mut img = Image::open(Cursor::new(image(0, layout))).unwrap();
    assert!(matches!(
        check_image(&mut img),
        Err(Rejection::Missing("data/big/miscload.big"))
    ));
}

#[test]
fn bounds_reads_and_tree_offsets() {
    let mut img = Image::open(Cursor::new(image(0, skate_layout(b"XEX2")))).unwrap();
    let entry = img.find("default.xex").unwrap().unwrap();
    assert!(img.read(&entry, 0, 5).is_err());
    // A child pointing backwards is a loop.
    let mut bytes = image(0, skate_layout(b"XEX2"));
    let root = 34 * SECTOR as usize;
    let first_len = (14 + "default.xex".len()).div_ceil(4) * 4;
    bytes[root + first_len + 2..root + first_len + 4].copy_from_slice(&1u16.to_le_bytes());
    let mut img = Image::open(Cursor::new(bytes)).unwrap();
    let root = img.root().clone();
    assert!(img.list(&root).is_err());
}

#[test]
fn admits_folders_and_checks_the_executable() {
    let dir = std::env::temp_dir().join(format!("skate_source_test_{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    for file in REQUIRED_FILES {
        let path = dir.join(file);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, b"XEX2synthetic").unwrap();
    }
    assert!(admit(Some(&dir.join("default.xex"))).is_ok());
    std::fs::write(dir.join("default.xex"), b"MZ").unwrap();
    assert!(matches!(admit(Some(&dir)), Err(Rejection::NotXex)));
    std::fs::remove_file(dir.join("data/big/db.big")).unwrap();
    assert!(matches!(
        admit(Some(&dir)),
        Err(Rejection::Missing("data/big/db.big"))
    ));
    assert!(matches!(admit(None), Err(Rejection::NotConfigured)));
    std::fs::remove_dir_all(&dir).unwrap();
}
